// Build the slim client search index from data/sites.json (BACKLOG T-066).
//
//   node scripts/build-search-index.mjs           # write src/lib/generated/search-index.ts
//   node scripts/build-search-index.mjs --check   # exit 1 if the file on disk is stale
//
// READ-ONLY on the corpus. This script never writes data/sites.json — the
// corpus is hand-curated and cited (constitution rules 2 and 5); this only
// projects it. The emitted file is gitignored and regenerated by the `prebuild`,
// `predev` and `pretest` npm hooks, so it cannot go stale.
//
// ---------------------------------------------------------------------------
// WHY THIS EXISTS
// ---------------------------------------------------------------------------
// SiteFilters.tsx imports the whole corpus, so every list page ships all of it
// to the browser. Two thirds of that payload is fields no list page ever reads:
// `story` (legend prose), `sources`, coordinates, `access`, `wiki`, `patron`,
// `disputedCircuits`. This keeps exactly the fields `search.ts` searches and
// SiteFilters renders, and nothing else.
//
// Measured on this corpus, 1,126 records (gzip -9 of the emitted JS module —
// the same figure this script prints when it runs, so it is reproducible):
//
//   full corpus, as it ships today ..................... 309.0 kB
//   slim fields, row objects, short keys ............... 200.6 kB
//   slim fields, COLUMN-oriented (what this emits) ..... 183.6 kB
//
// ---------------------------------------------------------------------------
// WHY COLUMNS, NOT ROWS WITH SHORT KEYS
// ---------------------------------------------------------------------------
// Short keys ("n" for "name") save almost nothing: gzip already reduces a key
// repeated 1,126 times to a few bytes. The real constraint is gzip's 32 kB
// sliding window. In row order, one record's `name` sits ~1 kB away from the
// next record's `name`, so the whole corpus is inside the window and repeats
// dedupe — but the window is also full of unrelated text. In column order every
// value sits next to a value of the same kind, and the columns that share
// vocabulary can be placed inside one window of each other. That is worth
// 16.9 kB, ten times what short keys are worth.
//
// COLUMN_ORDER below is therefore load-bearing, not cosmetic:
//   1. low-cardinality enumerations first — 1,126 copies of "Hindu" or "India"
//      collapse to nothing and cost the window almost no budget;
//   2. dates, then the attribution vocabulary (style / dynasty / deity), which
//      repeats across records;
//   3. `native` — Indic scripts, sharing no substrings with anything else;
//   4. `significance` — the prose bulk, 107.8 kB of the 183.6 kB total;
//   5. the proper-noun family LAST and ADJACENT: name, id, place, alt. `id` is
//      a slug built from the name and the place, so these four must land inside
//      one 32 kB window of each other. Splitting them costs 1.5 kB.
//
// ---------------------------------------------------------------------------
// WHY `significance` IS NOT TRUNCATED — see SIGNIFICANCE_MAX_CHARS below
// ---------------------------------------------------------------------------
// `significance` is in `haystackOf` in search.ts, so every character clipped off
// it is full-text search recall deleted. Measured against 9,207 queries drawn
// from the significance vocabulary itself (every token >= 4 characters, plus a
// deterministic 1-in-7 sample of its bigrams), scoring each variant against the
// hits the untruncated text finds:
//
//   cap    records clipped   index gz   token recall   searches left with 0 hits
//   240    669 / 1126        160.4 kB    85.24%        1265
//   320    321 / 1126        175.0 kB    94.61%         452
//   400    101 / 1126        180.9 kB    98.27%         116
//   480     33 / 1126        182.8 kB    99.47%          31
//   none      0 / 1126       183.6 kB   100.00%           0
//
// Once the dead fields are gone and the layout is columnar, truncation is no
// longer where the bytes are. Going from no cap to 400 characters saves 2.7 kB —
// 1.5% — and costs 116 searches that find a record today and would then find
// nothing. On a corpus whose entire claim is that it does not hide what it has
// sourced, that is the wrong trade, so: no cap.
//
// The knob is left in place because it is the honest place to make that call
// again. If the corpus grows an order of magnitude (the /about roadmap says it
// will), a cap is still not the answer — splitting `significance` into a chunk
// the browser fetches on the first keystroke leaves 75.8 kB on the critical path
// with the full text still searchable. See the note at the foot of
// src/lib/search-index.ts.

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { gzipSync } from "node:zlib";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CORPUS = path.join(ROOT, "data", "sites.json");
const OUT_DIR = path.join(ROOT, "src", "lib", "generated");
const OUT = path.join(OUT_DIR, "search-index.ts");
// `significance` is emitted separately so it can be fetched on the first
// keystroke instead of on page load. It is 209 kB of the index's 345 kB gzipped
// at 2,271 records — 61% — and `search.ts` only reads it once someone types.
const OUT_TEXT = path.join(OUT_DIR, "search-index-text.ts");
const TEXT_COLUMN = "significance";

/**
 * Every field the index carries, in the emitted column order.
 *
 * `search.ts` searches: name, alt, native, deity, deities, deityGroup, place,
 * state, country, dynasty, style, circuits, significance — and facets on
 * tradition, country, state, circuits, tier, deities, deityGroup and built (via
 * era). SiteFilters additionally renders id, name, place, state, tradition,
 * dynasty, built and builtDisplay.
 *
 * `deities` and `deityGroup` are on the CRITICAL path, not in the deferred
 * chunk with `significance`. They are facets: the dropdowns have to be built
 * and counted before anyone types, so deferring them would leave the deity
 * filter empty on page load — the one moment it is most likely to be used. They
 * are also tiny, being drawn from a closed vocabulary of a few dozen words.
 *
 * Everything else in a record is deliberately absent. Adding a field here is a
 * decision to ship it to every visitor of every list page — measure first.
 */
export const COLUMN_ORDER = [
  // 1. enumerations
  "tradition", "tier", "country", "state", "circuits",
  // 2. dates and attribution vocabulary. `deities` and `deityGroup` sit beside
  //    `deity` for READABILITY — the three are one subject — and not for any
  //    measured packing benefit. Unlike the proper-noun family below, their
  //    placement is NOT load-bearing: measured on 3,002 records, moving them
  //    adjacent to `deity`, splitting them across the layout, or pushing them to
  //    the far end all land within 0.09 kB of each other. They cost +5.6 kB
  //    gzipped (+3.2%) wherever they go, because a closed vocabulary of ~58 tags
  //    repeated across 2,800 records compresses to nearly nothing either way.
  "built", "builtDisplay", "style", "dynasty", "deityGroup", "deities", "deity",
  // 3. native scripts
  "native",
  // 4. the prose bulk
  "significance",
  // 5. the proper-noun family — keep these four adjacent
  "name", "id", "place", "alt",
];

/**
 * The only fields whose absence is a data bug rather than a curatorial choice.
 *
 * Everything else falls back to "" — constitution rule 2 says an unsourced fact
 * is omitted, so a record legitimately may carry no `significance`, `tier`,
 * `native` or `circuits`, and the index must survive that rather than refuse to
 * build. `""` is also 2 bytes where `null` is 4, and reads as falsy in
 * `facetValues`, exactly as an absent field does.
 */
const REQUIRED = new Set(["id", "name"]);

/**
 * How many characters of `significance` to keep, or `Infinity` for all of it.
 *
 * `Infinity` is a decision, not a default — see the measured table in the header
 * for what each lower value costs in search recall. Lowering this to 400 is the
 * one change that brings the index under a 182 kB budget; it also loses 116 of
 * 9,207 measured searches their only result. Re-run the numbers before moving it.
 */
const SIGNIFICANCE_MAX_CHARS = Infinity;

/** Clip to the last whole word at or before `max`; never mid-word unless the first word is longer. */
const clip = (text, max) => {
  if (text.length <= max) return text;
  const head = text.slice(0, max);
  const lastSpace = head.lastIndexOf(" ");
  return (lastSpace > max * 0.6 ? head.slice(0, lastSpace) : head).trimEnd();
};

const columnOf = (sites, field) => {
  if (field === "circuits") return sites.map((s) => s.circuits ?? []);
  // An untagged record emits [], never a placeholder tag: its dedication names
  // no figure, and the UI must be able to tell that from a tagged record.
  if (field === "deities") return sites.map((s) => s.deities ?? []);
  if (field === "significance") return sites.map((s) => clip(s.significance ?? "", SIGNIFICANCE_MAX_CHARS));
  if (field === "built") return sites.map((s) => {
    const built = s.built;
    if (!Array.isArray(built) || built.length !== 2 || built.some((y) => typeof y !== "number")) {
      throw new Error(`record "${s.id}" has no usable \`built\` pair; the era facet needs it`);
    }
    return [built[0], built[1]];
  });
  return sites.map((s) => {
    const value = s[field];
    if (typeof value === "string" && value !== "") return value;
    if (REQUIRED.has(field)) throw new Error(`record ${JSON.stringify(s.id)} has no ${field}`);
    return "";
  });
};

export const buildColumns = (sites) => {
  const columns = {};
  for (const field of COLUMN_ORDER) columns[field] = columnOf(sites, field);
  return columns;
};

/** Columns that are not `string[]`. Everything else is. */
const COLUMN_TS_TYPES = {
  circuits: "readonly (readonly string[])[]",
  deities: "readonly (readonly string[])[]",
  built: "readonly (readonly number[])[]",
};

/**
 * The emitted `SearchIndexColumns` declaration, derived from COLUMN_ORDER so the
 * two cannot drift: adding a column here is one edit, not two.
 */
const renderType = () => COLUMN_ORDER.filter((f) => f !== TEXT_COLUMN)
  .map((field) => `  readonly ${field}: ${COLUMN_TS_TYPES[field] ?? "readonly string[]"};`)
  .join("\n");

/**
 * The emitted module.
 *
 * The payload is a JSON string parsed at load rather than a JS object literal:
 * `JSON.parse` on a ~700 kB string is measurably faster than asking the JS
 * parser to walk the same data as syntax, and it costs nothing in transfer size
 * once gzipped. The banner is what a human sees first, on purpose.
 */
const render = (payload, count) => `// GENERATED FILE — DO NOT EDIT BY HAND.
//
// Written by scripts/build-search-index.mjs from data/sites.json.
// Regenerate with:  node scripts/build-search-index.mjs
// Any hand edit is lost on the next build, and \`--check\` will fail in CI.
//
// This is a projection of the corpus, not the corpus. data/sites.json stays
// canonical (constitution rule 6). Read it through src/lib/search-index.ts,
// which turns these columns back into records; nothing else should import it.

/** One array per field, all of length RECORD_COUNT, in corpus order. */
export type SearchIndexColumns = {
${renderType()}
};

/** How many records the corpus held when this file was written. */
export const RECORD_COUNT = ${count};

export const COLUMNS: SearchIndexColumns = JSON.parse(${payload});
`;

/** The deferred text column, loaded only when the visitor actually searches. */
const renderText = (payload, count) => `// GENERATED FILE — DO NOT EDIT BY HAND.
//
// Written by scripts/build-search-index.mjs from data/sites.json.
// Split out of search-index.ts on purpose: this is the ${TEXT_COLUMN} column,
// the bulk of the index, and search.ts reads it only once a visitor types. It is
// dynamically imported by src/lib/search-index.ts so it never lands on the
// critical path of a page nobody searches on.

/** Length matches RECORD_COUNT in search-index.ts, in the same corpus order. */
export const RECORD_COUNT = ${count};

export const TEXT: readonly string[] = JSON.parse(${payload});
`;

const main = () => {
  const check = process.argv.includes("--check");
  const sites = JSON.parse(readFileSync(CORPUS, "utf8"));
  if (!Array.isArray(sites) || sites.length === 0) {
    console.error(`build-search-index: ${CORPUS} is not a non-empty array`);
    process.exit(1);
  }

  const allColumns = buildColumns(sites);
  const { [TEXT_COLUMN]: textColumn, ...coreColumns } = allColumns;
  const payload = JSON.stringify(JSON.stringify(coreColumns));
  const textPayload = JSON.stringify(JSON.stringify(textColumn));
  const source = render(payload, sites.length);
  const textSource = renderText(textPayload, sites.length);

  if (check) {
    const onDisk = existsSync(OUT) ? readFileSync(OUT, "utf8") : null;
    const onDiskText = existsSync(OUT_TEXT) ? readFileSync(OUT_TEXT, "utf8") : null;
    if (onDisk === source && onDiskText === textSource) {
      console.log(`build-search-index: up to date (${sites.length} records)`);
      return;
    }
    console.error(
      `build-search-index: src/lib/generated/search-index.ts is ${onDisk === null ? "missing" : "stale"}.\n` +
      "  Run: node scripts/build-search-index.mjs",
    );
    process.exit(1);
  }

  mkdirSync(OUT_DIR, { recursive: true });
  writeFileSync(OUT, source);
  writeFileSync(OUT_TEXT, textSource);

  // Both figures are gzip -9 of a JS module, so they are like for like. The
  // banner and the type declaration above are erased by the bundler, so the
  // index figure is measured on what actually reaches the browser.
  const kb = (n) => `${(n / 1024).toFixed(1)} kB`;
  const gz = (text) => gzipSync(Buffer.from(text), { level: 9 }).length;
  const before = gz(`export default ${JSON.stringify(sites)};`);
  const after = gz(`export const COLUMNS=JSON.parse(${payload});`);
  const deferred = gz(`export const TEXT=JSON.parse(${textPayload});`);
  console.log(`build-search-index: ${sites.length} records -> src/lib/generated/search-index.ts`);
  console.log(`  corpus as it ships today  ${kb(before)} gzipped`);
  console.log(`  critical path             ${kb(after)} gzipped  (${Math.round((1 - after / before) * 100)}% smaller)`);
  console.log(`  deferred ${TEXT_COLUMN}     ${kb(deferred)} gzipped  (fetched on first keystroke)`);
};

// Only run when invoked as the entry point: search-index.test.ts imports
// `buildColumns` from here, and importing a module must not write files.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
